 'reset-filters':()=>{state.query='';state.filter='all';render();},
 'save-demo':()=>toast('Anteprima aggiornata. Nessuna configurazione reale è stata salvata.'),'cancel-demo':()=>toast('Modifiche dimostrative annullate.'),
 'export-menu':()=>modal('Importare ed esportare','Ambito sempre visibile, conferma prima delle operazioni.',exportOptions()),
 'csv-demo':()=>{const content='riferimento,titolo,gravita,stato\n'+visibleIncidents().map(x=>[x.ref,x.title,x.severity,x.status].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}));link.download='CIR_DEMO_incidenti.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Scaricato un CSV con i soli dati fittizi della demo.');},
