 'workflow-transfer':()=>modal('Workflow: import, export e copia','Tutti i percorsi già presenti restano raggiungibili.',`<div class="export-options">${[['Importa JSON','Il mapping conserva provenienza e dipendenze.','workflow-json'],['Esporta workflow','Scegli workflow e documenti necessari.','workflow-export'],['Copia da altro tenant','Seleziona il tenant sorgente secondo i permessi.','workflow-clone'],...(state.role==='superuser'?[['Importa nel catalogo','Pubblica una procedura nei Tenants Default.','catalog-upload']]:[])].map(([h,p,a])=>`<button class="export-option" data-action="${a}">${icon('flow')}<span><strong>${h}</strong><small>${p}</small></span>${icon('arrow')}</button>`).join('')}</div>`),
