 'workflow-export':()=>genericInfo('Export workflow','Esporta la struttura con le dipendenze e i documenti necessari, conservando la provenienza dei parametri condivisi.'),
 'workflow-clone':()=>genericInfo('Copia tra tenant','La copia conserva i controlli sui tenant accessibili e crea elementi locali con riferimenti coerenti.'),
