 'upload-document':uploadDocument,'upload-confirm':()=>{const file=$('#upload-file')?.files[0];if(!file)return toast('Seleziona un file per completare la dimostrazione.');const mode=$('#upload-mode').value;$('#modal').close();toast(`Demo: ${file.name} selezionato per ${mode}. Nessun file è stato caricato.`);},
