 'generate-forms':()=>genericInfo('Generazione moduli','Seleziona i template consentiti dalla fase, verifica campi e mapping e genera i PDF previsti.'),
 'alfresco-folder':()=>genericInfo('Directory Alfresco','Il naming resta incident-<id> - <nome-incidente> e il report automatico segue le impostazioni tenant.'),
 'alfresco-check':()=>toast('Solo anteprima: nessuna connessione Alfresco è stata effettuata.'),
 'add-action':()=>modal('Documenta un’azione','Ogni attività resta collegata all’incidente.',`<div class="modal-fields"><div class="field"><label>Tipo di azione</label><select aria-label="Tipo di azione"><option>Analisi delle evidenze</option><option>Contenimento</option><option>Comunicazione</option></select></div><div class="field"><label>Descrizione</label><textarea aria-label="Descrizione azione" placeholder="Attività svolta e risultato"></textarea></div></div>`,btn('Salva nella demo','action-save','check','primary')),
 'action-save':()=>{$('#modal').close();toast('Azione dimostrativa confermata. Il registro reale non è stato modificato.');},
 'action-more':()=>modal('Opzioni dell’azione','Comandi nel contesto della singola attività.',`<label class="toggle-row">Includi l’azione nei report (esportabile)<input type="checkbox" checked></label><div class="actions-inline" style="margin-top:16px">${btn('Modifica','edit-action','edit')}${btn('Allegati','action-attachments','doc')}${btn('Elimina azione','delete-guard','trash','danger')}</div>`),'audit-export':()=>genericInfo('Esporta audit CSV','Il comando conserva il filtro corrente e i permessi del registro di audit. La demo non scarica log reali.'),'edit-action':()=>action('add-action'),'action-attachments':()=>genericInfo('Allegati dell’azione','Caricamento, download e rimozione degli allegati restano disponibili nel contesto della singola azione.'),
 'incident-pdf':()=>genericInfo('Report PDF','Il report dell’incidente mantiene contenuti e dati previsti. Questo pulsante è una dimostrazione della posizione del comando.'),
 'incident-more':()=>modal('Altre azioni dell’incidente','Comandi conservati, con conferme e permessi.',`<div class="export-options">${[['Clona incidente','Un nuovo incidente deve usare un workflow corrente.','incident-clone'],['Sposta tenant','Disponibile ai superuser con i controlli sui riferimenti.','incident-move'],['Promemoria','Crea, modifica o elimina promemoria specifici.','reminders'],['Elimina incidente','Conferma esplicita e verifica dei permessi.','delete-guard']].filter(x=>x[2]==='reminders'||canEditIncident()&&(x[2]!=='incident-move'||state.role==='superuser')).map(([h,p,a])=>`<button class="export-option" data-action="${a}">${icon('shield')}<span><strong>${h}</strong><small>${p}</small></span></button>`).join('')}</div>`),
 'incident-clone':newIncident,'incident-move':()=>genericInfo('Sposta incidente','Il superuser sceglie il tenant di destinazione. La migrazione dei riferimenti e i vincoli esistenti restano invariati.'),
